import os
from azure.cosmos import CosmosClient, PartitionKey, exceptions

class DatabaseClient:
    def __init__(self):
        self.url = os.getenv('COSMOS_DB_URL')
        self.key = os.getenv('COSMOS_DB_KEY')
        self.client = CosmosClient(self.url, self.key)
        self.database_name = os.getenv('COSMOS_DB_DATABASE')
        self.container_name = os.getenv('COSMOS_DB_CONTAINER')
        self.database = self.client.get_database_client(self.database_name)
        self.container = self.database.get_container_client(self.container_name)

    def upsert_item(self, item):
        try:
            self.container.upsert_item(body=item)
        except exceptions.CosmosHttpResponseError as e:
            print(f'Error upserting item: {e}')
            raise

def main():
    db_client = DatabaseClient()
    item = {
        'id': '1',
        'name': 'John Doe',
        'age': 30
    }
    db_client.upsert_item(item)

if __name__ == '__main__':
    main()

import os
from azure.cosmos import CosmosClient, PartitionKey, exceptions

class DatabaseClient:
    def __init__(self):
        self.url = os.getenv('COSMOS_DB_URL')
        self.key = os.getenv('COSMOS_DB_KEY')
        self.client = CosmosClient(self.url, self.key)
        self.database_name = os.getenv('COSMOS_DB_DATABASE')
        self.container_name = os.getenv('COSMOS_DB_CONTAINER')
        self.database = self.client.get_database_client(self.database_name)
        self.container = self.database.get_container_client(self.container_name)

    def query_items(self, query):
        try:
            items = list(self.container.query_items(
                query=query,
                enable_cross_partition_query=True
            ))
            return items
        except exceptions.CosmosHttpResponseError as e:
            print(f'Error querying items: {e}')
            raise

def main():
    db_client = DatabaseClient()
    query = 'SELECT * FROM c WHERE c.age > 30'
    items = db_client.query_items(query)
    for item in items:
        print(item)

if __name__ == '__main__':
    main()

import os
from azure.cosmos import CosmosClient, PartitionKey, exceptions

class DatabaseClient:
    def __init__(self):
        self.url = os.getenv('COSMOS_DB_URL')
        self.key = os.getenv('COSMOS_DB_KEY')
        self.client = CosmosClient(self.url, self.key)
        self.database_name = os.getenv('COSMOS_DB_DATABASE')
        self.container_name = os.getenv('COSMOS_DB_CONTAINER')
        self.database = self.client.get_database_client(self.database_name)
        self.container = self.database.get_container_client(self.container_name)

    def conditional_update(self, item_id, item):
        try:
            self.container.replace_item(item_id, item)
        except exceptions.CosmosHttpResponseError as e:
            print(f'Error updating item: {e}')
            raise

def main():
    db_client = DatabaseClient()
    item_id = '1'
    item = {
        'id': item_id,
        'name': 'Jane Doe',
        'age': 35
    }
    db_client.conditional_update(item_id, item)

if __name__ == '__main__':
    main()

from typing import Any, Dict

class DatabaseModels:
